  for (const p of state.players) {
    if (!seated(p)) continue;
    if (p.ctrl === 'cpu') root.SproAI ? root.SproAI.think(state, p) : null;
    updatePlayer(state, p);
  }
  for (const e of state.enemies) updateEnemy(state, e);
